package javafx.application; import javafx.stage.Stage; public abstract class Application { public abstract void start(Stage stage) throws Exception; public static void launch(String... args){ try{ var cls=Class.forName(Thread.currentThread().getStackTrace()[2].getClassName()); ((Application)cls.getDeclaredConstructor().newInstance()).start(new Stage()); }catch(Exception e){ throw new RuntimeException(e);} } }
